#!/usr/bin/env bash
# R265 (2026-09-06): R259 headline ladders (c1-c64, MTP4 and MTP0) with every rung run twice on the same server; the R259/R261 ladders ran each rung once and their c2 rung carried a ~1 s first-encounter stall (TTFT 1.02 s on one request), so the second pass is the steady-state aggregate.
# R259 (2026-09-06): TP2 depth-4 identity ladders (MTP4 and MTP0) with graph capture and the draft-only INT4 head (R257 configuration, R256 image). Arg 1: pid to wait for.
set -uo pipefail
out=/mnt/fast-ai/bench-results; S=/home/steve/b70-optimization-lab/experiments/qwen38-27b-b70/scripts; R=/home/steve/b70-optimization-lab/repro
[[ -n "${1:-}" ]] && while kill -0 "$1" 2>/dev/null; do sleep 30; done
source $out/final-int4-config.env; IMAGE=neural-download/vllm-openai-xpu:qwen38-int4-draft-int4-head-r256; IMAGE_ID=sha256:f7696bcaefab1bc1c93e12cbde630b6e81bed8e00e41154ca2198e246c35dea3
TP=2; tpenv=(); DEPTH=4; RUN=${RUN:-r265}
LADDERS_ONLY=1 LADDER_REPEATS=${LADDER_REPEATS:-2} XPU_GRAPH=1 env "${tpenv[@]}" XPU_EXTENSION_SHA256_OVERRIDE=${XPU_EXTENSION_SHA256} VLLM_XPU_FA_SERIAL_SPEC_DECODE=1 VLLM_BATCH_INVARIANT=1 VLLM_XPU_DRAFT_LM_HEAD_INT4=1 VLLM_XPU_W4A16_DETERMINISM_PAD=0 VLLM_XPU_W4A16_DETERMINISM_PAD_HIGH=0 MODEL_DIR=/mnt/fast-ai/llm-models/qwen3.8-27b-int4-autoround-gptq-relabel MODEL_MANIFEST=$R/qwen38-27b-autoround-int4-b70/manifests/model-gptq-relabel-r212.json QUANTIZATION=${QUANTIZATION:-gptq} VLLM_XPU_FP8_BLOCK_W8A16=0   XPU_OPS_SHA256_OVERRIDE=${XPU_OPS_SHA256} VLLM_XPU_GDN_SPEC_GROUP=${GDN_SPEC_GROUP:-16} VLLM_XPU_GDN_PREFILL_GROUP=${GDN_PREFILL_GROUP:-1} LAYERNORM_SHA256_OVERRIDE=50cf5f4f9c72f679e4318cd3e3e021a844f59ac188a891d9a4f9638188f4bce8 GEMMA_TRITON=0 RMSNORM_TRITON=0 GDN_SPLIT_MIXED=1   COMPILATION_CONFIG='{"cudagraph_mode":"FULL_DECODE_ONLY","cudagraph_capture_sizes":[1,2,3,4,5,6,8],"max_cudagraph_capture_size":8,"splitting_ops":[],"inductor_compile_config":{"combo_kernels":false,"benchmark_combo_kernel":false,"deterministic":true,"split_reductions":false,"triton.autotune_pointwise":false,"benchmark_epilogue_fusion":false}}' IMAGE_OVERRIDE=${IMAGE} IMAGE_ID_OVERRIDE=${IMAGE_ID}   SPECULATIVE_CONFIG="{\"method\":\"qwen3_next_mtp\",\"num_speculative_tokens\":${DEPTH:-4}}" ROOT=$out/qwen38-int4-graph-drafthead-tp${TP}-mtp${DEPTH}-ladders-20260906-${RUN} bash $S/run-20260902-qwen38-fp8-triton-rmsnorm-r152.sh
